tool_input_args.value:
cd /workspace && python3 -c "
import json, sqlite3

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row

INVALID_CABIN_KEYS = {'premium_economy', 'first'}
fixed = 0

for r in conn.execute(\"SELECT flight_id, dates_json FROM flights WHERE source_skill='tau2Airline'\"):
    dj = json.loads(r['dates_json'] or '{}')
    changed = False
    for date, info in dj.items():
        # Fix invalid status values
        if info.get('status') == 'active':
            info['status'] = 'available'
            changed = True
        # Strip invalid cabin keys from prices and available_seats
        for key in ('prices', 'available_seats'):
            if key in info:
                for bad in INVALID_CABIN_KEYS:
                    if bad in info[key]:
                        del info[key][bad]
                        changed = True
    if changed:
        conn.execute('UPDATE flights SET dates_json=? WHERE flight_id=?', (json.dumps(dj), r['flight_id']))
        fixed += 1

conn.commit()
conn.close()
print(f'Fixed {fixed} more flight records')
" 2>&1

